import assert from 'node:assert/strict';
import {execFileSync,spawnSync} from 'node:child_process';
import {createHash,randomUUID} from 'node:crypto';
import {existsSync,mkdirSync,mkdtempSync,readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {createRequire} from 'node:module';
import {tmpdir} from 'node:os';
import {dirname,join,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
const coreRoot=resolve(process.env.SPEX_PROBE_CORE),req=createRequire(join(coreRoot,'package.json'));
const {CoreService}=await import(pathToFileURL(join(coreRoot,'dist/service.js')));
const {fakeAdapterImports}=await import(pathToFileURL(join(coreRoot,'dist/testing/fake-adapter.js')));
const {WebSocket}=req('ws');
const scratch=mkdtempSync(join(tmpdir(),'spex-github-rebase-'));
const proof={platform:process.platform,versions:process.versions,scratch,checks:{},modelCalls:0};
let service,socket;
const output=process.env.SPEX_PROBE_OUTPUT||'github-install-proof.json';
const sha=b=>createHash('sha256').update(b).digest('hex');
try {
 const project=join(scratch,'project');mkdirSync(project);
 const git=(...args)=>execFileSync('git',args,{cwd:project,encoding:'utf8',windowsHide:true}).trim();
 git('init','-q','--initial-branch=main');writeFileSync(join(project,'README.md'),'Isolated installation boundary check.\n');git('add','README.md');git('-c','user.name=Verification','-c','user.email=verification@example.invalid','-c','commit.gpgsign=false','commit','-qm','Fixture');
 const account=join(scratch,'account');mkdirSync(join(account,'.codex'),{recursive:true});
 const config=join(scratch,'playbook.config.yaml');writeFileSync(config,'captain:\n  adapter: codex\n  model: test\nplayers:\n  dev.coder:\n    adapter: codex\n    model: test\nplaybooks:\n  code:\n    roles:\n      coder: dev.coder\n');
 const token=randomUUID();
 const {imports}=fakeAdapterImports({fallback:{result:'probe does not request a model turn'}});
 service=await CoreService.start({token,configPath:config,dataDir:join(scratch,'state'),home:account,own:'verifier',watchConfig:false,env:{...process.env,SPEX_HOST_URL:'http://127.0.0.1:9'},adapterImports:imports,adapterRuntime:()=>({usable:true})});
 socket=new WebSocket(`ws://127.0.0.1:${service.port()}/?token=${token}`);
 const pending=new Map();let seq=0;
 socket.on('message',data=>{const m=JSON.parse(String(data));if(m.type==='reply'){const p=pending.get(m.id);if(p){clearTimeout(p.timer);pending.delete(m.id);m.ok?p.resolve(m.result):p.reject(Error(m.error.code+': '+m.error.message));}}});
 await new Promise((yes,no)=>{socket.once('open',yes);socket.once('error',no)});
 const rpc=(type,fields={})=>new Promise((yes,no)=>{const id='p'+(++seq);const timer=setTimeout(()=>{pending.delete(id);no(Error('RPC timeout '+type));},180000);pending.set(id,{resolve:yes,reject:no,timer});socket.send(JSON.stringify({type,id,...fields}));});
 const registered=await rpc('project.register',{path:project});proof.projectId=registered.id;
 const request={kind:'git',git:'https://github.com/yangbobo2021/app-delivery-acceptance-spex.git',rev:'main'};
 const remote=spawnSync('git',['ls-remote',request.git,'refs/heads/main'],{encoding:'utf8',timeout:30000,windowsHide:true});
 proof.gitPreflight={status:remote.status,stdout:remote.stdout,stderr:remote.stderr,error:remote.error?.message};assert.equal(remote.status,0,JSON.stringify(proof.gitPreflight));
 await rpc('environment.request',{repository:registered.id,name:'yangbobo2021/app-delivery-acceptance',request,wait:true});
 const state=await rpc('environment.get',{repository:registered.id});assert.equal(state.error,null,JSON.stringify(state));
 const pkg=state.packages.find(p=>p.name==='yangbobo2021/app-delivery-acceptance');assert(pkg?.installed,JSON.stringify(pkg));proof.checks.githubInstall=pkg;
 const catalog=await rpc('environment.playbooks',{projectId:registered.id});const row=catalog.project?.find(p=>p.id==='acceptance-orchestrate');assert(row?.present,JSON.stringify(catalog));assert(row.folder);proof.checks.catalog=row;
 const entryPath=join(row.folder,'acceptance-orchestrate.registry.mjs');const module=await import(pathToFileURL(entryPath));assert.equal(module.spexRegistryContract,3);assert.equal(module.default.id,'acceptance-orchestrate');assert.equal(typeof module.default.createRuntime,'function');proof.checks.entryLoadsOnHostEngine=true;
 const roles=Object.fromEntries(module.default.requiredRoleIds.map(id=>[id,'dev.coder']));
 const configured=await rpc('config.edit',{repository:registered.id,op:{kind:'playbook.add',playbookId:'acceptance-orchestrate',roles}});assert.equal(configured.status,'valid',JSON.stringify(configured));
 const session=await rpc('session.create',{projectId:registered.id});assert(session.id);proof.checks.sessionCreated=session.id;
 const exported=join(project,'.agents','skills','app-delivery-acceptance');assert(existsSync(join(exported,'SKILL.md')),'Codex Skill was not exported');
 const installed=join(project,'.spex','packages','yangbobo2021','app-delivery-acceptance','skills','en','app-delivery-acceptance');
 function files(root,prefix=''){return Object.fromEntries(readdirSync(join(root,prefix),{withFileTypes:true}).flatMap(e=>{const rel=prefix+e.name;if(e.isDirectory())return Object.entries(files(root,rel+'/'));assert(e.isFile(),'Nonregular exported entry');return [[rel,sha(readFileSync(join(root,rel)))]]}));}
 const exportedFiles=files(exported),installedFiles=files(installed);assert.deepEqual(exportedFiles,installedFiles);assert.equal(JSON.parse(readFileSync(join(exported,'SPEX-INSTALL.json'))).package_version,'0.4.14');proof.checks.codexSkill={version:'0.4.14',files:Object.keys(exportedFiles).length,digest:sha(JSON.stringify(exportedFiles))};
 const lockText=readFileSync(join(project,'spex.lock'),'utf8');proof.lockSha256=sha(lockText);proof.lock=lockText;
 await rpc('environment.install',{repository:registered.id,wait:true});assert.equal(sha(readFileSync(join(project,'spex.lock'))),proof.lockSha256);assert.deepEqual(files(exported),exportedFiles);proof.checks.reinstallKeepsLockAndSkillBytes=true;
 proof.status='passed';
} catch(error){proof.status='failed';proof.error=error.stack;throw error;}finally{if(socket){socket.close();socket.terminate();}if(service)await service.stop();writeFileSync(output,JSON.stringify(proof,null,2));console.log(JSON.stringify({status:proof.status,platform:proof.platform,checks:Object.keys(proof.checks),output}));}
